"""原典22画像確認後の手書き初稿。公式正答から解説を生成しない。"""
import json,copy
from pathlib import Path
P=Path(__file__).resolve().parents[2]
R={r['question_id']:r for r in json.loads((P/'extracted/logs/S7_060_selection.json').read_text())['records']}
I=json.loads((P/'extracted/logs/S7_060_initial_independent.json').read_text())
T=json.loads((P/'config/authored_batches/S7_059_environment_finish_middle_corrected.json').read_text())['questions'][0]
Q=[]
def add(y,n,title,cid,values,reasons,sol,knowledge,section,d='basic_5_1',negative=True,ambiguity='',refs=None,figure=False,calc=False,law=False,conditions=None):
 q=f'{y}-REG-BASIC-5-{n}'; r=R[q]; e=copy.deepcopy(T); a=int(I['answers'][q]); assert len(values)==len(reasons)==5
 choices={str(i):{'value':v,'verdict':('不適切・選択対象' if i==a else '条件内で適切') if negative else ('適切・選択対象' if i==a else '不適切'),'reason':z} for i,(v,z) in enumerate(zip(values,reasons),1)}
 e.update(question_id=q,source_sha256=r['source_sha256'],stem=title,summary=title,conditions=conditions or {'原典':'全五肢と否定方向・組合せ表を画像確認。','資料時点':r['era_year']+'の指定資料・統計年を保持し、後年値に置換しない。'},choices=choices,figures='図の数値又は組合せ表を独自要約。原典画像は確認用のみ。' if figure else '文章五肢を独自要約。',ambiguity=ambiguity,evidence=[f"extracted/pages/{r['source_year_directory']}/basic/page_{int(r['source_page']):03d}.png"],core_concept=title,required_knowledge=knowledge,solution=sol,answer_reason=sol,independent_answer=I['answers'][q],independent_solution_note='原典22画像照合後の独立判断をS7_060_initial_independent.jsonへ先に記録。完全盲検とはしない。',learning_points=knowledge+' 否定方向と資料年、分母と単位を確認して五肢へ戻る。',theory_references=[section],discipline_id=d,concept_id=cid,cross_concepts=[],classification_reason='原典の全条件と五肢を確認：'+title,calculation='true' if calc else 'false',figure='true' if figure else 'false',law='true' if law else 'false',evaluation={'knowledge_novelty':'2','reasoning_steps':'2','calculation_load':'1' if calc else '0','figure_reading':'1' if figure else '0','difficulty':'3' if ambiguity else '2','difficulty_reason':'対象時点と定義を分け、各肢を独立に判断する。'},citations=refs or [],foundationality='high',transferability='high')
 Q.append(e)
def table(y,n,title,cid,values,target,sol,knowledge,section,**kw):
 reasons=[('独立に求めた組合せ '+target+' と一致する。' if v==target else '独立に求めた組合せ '+target+' と異なる。') for v in values]
 add(y,n,title,cid,values,reasons,sol,knowledge,section,negative=False,figure=True,**kw)

